import { BN } from '@coral-xyz/anchor';
import { AsyncData, QuoteParams, RouteOutput, RouteParams, safeBNToNumber } from '../swap_api_utils';
import Decimal from 'decimal.js';

export function addPricesAndPriceImpactToRouteOutput(
  params: RouteParams | QuoteParams,
  route: RouteOutput,
): RouteOutput {
  if (
    route !== undefined &&
    route.birdeyeTokenInPriceInSol &&
    route.birdeyeTokenOutPriceInSol &&
    route.inputTokenDecimals &&
    route.outputTokenDecimals
  ) {
    if (params.swapType === 'exactIn') {
      route.priceImpactBps = Math.max(
        calculatePriceImpactBps(
          route.birdeyeTokenInPriceInSol,
          route.birdeyeTokenOutPriceInSol,
          new Decimal(route.amountsExactIn.amountIn.toString()).div(new Decimal(10).pow(route.inputTokenDecimals)),
          new Decimal(route.amountsExactIn.amountOut.toString()).div(new Decimal(10).pow(route.outputTokenDecimals)),
        ),
        0,
      );
      route.guaranteedPriceImpactBps = Math.max(
        calculatePriceImpactBps(
          route.birdeyeTokenInPriceInSol,
          route.birdeyeTokenOutPriceInSol,
          new Decimal(route.amountsExactIn.amountIn.toString()).div(new Decimal(10).pow(route.inputTokenDecimals)),
          new Decimal(route.amountsExactIn.amountOutGuaranteed.toString()).div(
            new Decimal(10).pow(route.outputTokenDecimals),
          ),
        ),
        0,
      );
      route.simulatedPriceImpactBps = route.amountsExactIn.amountOutSimulated
        ? Math.max(
            calculatePriceImpactBps(
              route.birdeyeTokenInPriceInSol,
              route.birdeyeTokenOutPriceInSol,
              new Decimal(route.amountsExactIn.amountIn.toString()).div(new Decimal(10).pow(route.inputTokenDecimals)),
              new Decimal(route.amountsExactIn.amountOutSimulated.toString()).div(
                new Decimal(10).pow(route.outputTokenDecimals),
              ),
            ),
            0,
          )
        : undefined;
    } else {
      route.priceImpactBps = Math.max(
        calculatePriceImpactBps(
          route.birdeyeTokenInPriceInSol,
          route.birdeyeTokenOutPriceInSol,
          new Decimal(route.amountsExactOut.amountOut.toString()).div(new Decimal(10).pow(route.outputTokenDecimals)),
          new Decimal(route.amountsExactOut.amountIn.toString()).div(new Decimal(10).pow(route.inputTokenDecimals)),
        ),
        0,
      );
      route.guaranteedPriceImpactBps = Math.max(
        calculatePriceImpactBps(
          route.birdeyeTokenInPriceInSol,
          route.birdeyeTokenOutPriceInSol,
          new Decimal(route.amountsExactOut.amountOut.toString()).div(new Decimal(10).pow(route.outputTokenDecimals)),
          new Decimal(route.amountsExactOut.amountInGuaranteed.toString()).div(
            new Decimal(10).pow(route.inputTokenDecimals),
          ),
        ),
        0,
      );
      route.simulatedPriceImpactBps = route.amountsExactOut.amountInSimulated
        ? Math.max(
            calculatePriceImpactBps(
              route.birdeyeTokenInPriceInSol,
              route.birdeyeTokenOutPriceInSol,
              new Decimal(route.amountsExactOut.amountOut.toString()).div(
                new Decimal(10).pow(route.outputTokenDecimals),
              ),
              new Decimal(route.amountsExactOut.amountInSimulated.toString()).div(
                new Decimal(10).pow(route.inputTokenDecimals),
              ),
            ),
            0,
          )
        : undefined;
    }
  }
  return route;
}

export function calculatePriceImpactBps(
  baseFixedTokenPrice: number,
  baseExpectedTokenPrice: number,
  amountFixedToken: Decimal,
  amountExpectedToken: Decimal,
): number {
  const expectedAmountB = amountFixedToken.mul(baseFixedTokenPrice).div(baseExpectedTokenPrice);

  // Calculate the actual output vs expected output ratio
  const outputRatio = amountExpectedToken.div(expectedAmountB);

  // Calculate price impact as a percentage
  // If outputRatio < 1, we're getting less than expected (negative price impact)
  const priceImpactPercent = new Decimal(1).sub(outputRatio).mul(100);

  const priceImpactBps = priceImpactPercent.mul(100);

  // Return the price impact (positive means unfavorable to the user)
  return priceImpactBps.toNumber();
}

export function getAsyncDataFromApiRouteOutput(routes: RouteOutput[]): AsyncData {
  let asyncData: AsyncData = {
    inputMintProgramOwner: undefined,
    outputMintProgramOwner: undefined,
    inputTokenDecimals: undefined,
    outputTokenDecimals: undefined,
    birdeyeTokenInPriceInSol: undefined,
    birdeyeTokenOutPriceInSol: undefined,
  };
  routes.forEach((route) => {
    if (route.inputMintProgramOwner) {
      asyncData.inputMintProgramOwner = route.inputMintProgramOwner;
    }
    if (route.outputMintProgramOwner) {
      asyncData.outputMintProgramOwner = route.outputMintProgramOwner;
    }
    if (route.inputTokenDecimals) {
      asyncData.inputTokenDecimals = route.inputTokenDecimals;
    }
    if (route.outputTokenDecimals) {
      asyncData.outputTokenDecimals = route.outputTokenDecimals;
    }
    if (route.birdeyeTokenInPriceInSol) {
      asyncData.birdeyeTokenInPriceInSol = route.birdeyeTokenInPriceInSol;
    }
    if (route.birdeyeTokenOutPriceInSol) {
      asyncData.birdeyeTokenOutPriceInSol = route.birdeyeTokenOutPriceInSol;
    }
  });
  return asyncData;
}

export function addAsyncDataToRouteOutput(route: RouteOutput, asyncData: AsyncData): RouteOutput {
  route.inputMintProgramOwner = asyncData.inputMintProgramOwner;
  route.outputMintProgramOwner = asyncData.outputMintProgramOwner;
  route.inputTokenDecimals = asyncData.inputTokenDecimals;
  route.outputTokenDecimals = asyncData.outputTokenDecimals;
  route.birdeyeTokenInPriceInSol = asyncData.birdeyeTokenInPriceInSol;
  route.birdeyeTokenOutPriceInSol = asyncData.birdeyeTokenOutPriceInSol;
  return route;
}
